async function processMessage(message: ServiceBusReceivedMessage): Promise<void> {
    // Simulate some processing time
    await new Promise(resolve => setTimeout(resolve, 100));
}

// Run the demo
main().catch((error) => {
    console.error("Error running demo:", error);
